mapper.update:
update alarm_stop_event set event_status = 'APPLIED', applied_stop_time = stop_time, applied_time = now(), delete_after = #{deleteAfter}, lock_token = null, locked_at = null, updated_time = now() where event_status = 'PROCESSING' and lock_token = #{lockToken} and (
(id = #{event.id} and event_version = #{event.eventVersion})
)

mapper.delete:
delete from alarm_stop_event
where event_status = 'APPLIED'
  and delete_after is not null
  and delete_after <= #{now}
limit #{limit}
